		http.Error(w, "Invalid frame number", http.StatusBadRequest)
		return
	}

	// Validate file type
	buff := make([]byte, 512)
	_, err = file.Read(buff)
	if err != nil || http.DetectContentType(buff) != "video/mp4" {
