  const timestamp = new Date().toISOString();
  db.run(`INSERT INTO clicks (id, timestamp) VALUES (?, ?)`, [id, timestamp], function(err) {
    if (err) {
      res.status(400).send('Invalid request');
    } else {
      res.status(201).send('Click registered successfully');
    }
  });
});

