import fastify from 'fastify';
import sqlite3 from 'sqlite3';
import { open } from 'sqlite';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import dotenv from 'dotenv';

dotenv.config();

const app = fastify();
const APP_SECRET = process.env.APP_SECRET || 'defaultsecret';

let db;

// Initialize SQLite database
async function initDb() {
  db = await open({
    filename: 'db.sqlite3',
    driver: sqlite3.Database
  });

  await db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT UNIQUE,
      password TEXT,
      name TEXT
    )
  `);
}

// Register endpoint
app.post('/register', async (request, reply) => {
  const { email, password, name } = request.body;

  if (!email || !password || !name) {
    return reply.status(400).send({ message: 'Invalid data' });
  }

  try {
    const existingUser = await db.get('SELECT * FROM users WHERE email = ?', [email]);
    if (existingUser) {
      return reply.status(400).send({ message: 'Email already in use' });
    }

    const hashedPassword = await bcrypt.hash(password, 10);
    await db.run('INSERT INTO users (email, password, name) VALUES (?, ?, ?)', [email, hashedPassword, name]);

    return reply.status(201).send({ message: 'Registration successful' });
  } catch (error) {
    return reply.status(500).send({ message: 'Internal server error' });
  }
});

// Login endpoint
app.post('/login', async (request, reply) => {
  const { email, password } = request.body;

  if (!email || !password) {
    return reply.status(401).send({ message: 'Invalid email or password' });
  }

  try {
    const user = await db.get('SELECT * FROM users WHERE email = ?', [email]);
    if (!user || !(await bcrypt.compare(password, user.password))) {
      return reply.status(401).send({ message: 'Invalid email or password' });
    }

    const token = jwt.sign({ id: user.id, email: user.email }, APP_SECRET, { expiresIn: '1h' });
    return reply.status(200).send({ token, message: 'Login successful' });
  } catch (error) {
    return reply.status(500).send({ message: 'Internal server error' });
  }
});

// Start server
const start = async () => {
  try {
    await initDb();
    await app.listen({ port: 5000, host: '0.0.0.0' });
    console.log('Server listening on http://0.0.0.0:5000');
  } catch (err) {
    console.error(err);
    process.exit(1);
  }
};

start();

const fastify = require('fastify')();
const { execFile } = require('child_process');

const safeFilterFlags = ['aux', 'aux -T', 'x'];

fastify.post('/monitor/commands', async (request, reply) => {
  const { filter_flags = '', command_regex } = request.body;

  if (!command_regex) {
    return reply.status(400).send({
      code: 400,
      message: 'command_regex is required'
    });
  }

  if (!safeFilterFlags.includes(filter_flags)) {
    return reply.status(400).send({
      code: 400,
      message: 'Invalid filter_flags'
    });
  }

  let regex;
  try {
    regex = new RegExp(command_regex);
  } catch (e) {
    return reply.status(400).send({
      code: 400,
      message: 'Invalid command_regex'
    });
  }

  execFile('ps', [filter_flags], (error, stdout, stderr) => {
    if (error) {
      return reply.status(500).send({
        code: 500,
        message: 'Error executing ps command'
      });
    }

    const processes = stdout.split('\n').slice(1).filter(line => regex.test(line)).map(line => {
      const parts = line.trim().split(/\s+/);
      return {
        processId: parseInt(parts[0], 10),
        processString: line
      };
    });

    reply.send(processes);
  });
});

fastify.listen({ port: 5000, host: '0.0.0.0' }, err => {
  if (err) {
    console.error(err);
    process.exit(1);
  }
  console.log('Server listening on http://0.0.0.0:5000');
});

const fastify = require('fastify')({ logger: true });
const multipart = require('@fastify/multipart');
const { execFile } = require('child_process');
const fs = require('fs');
const path = require('path');

// Register multipart plugin
fastify.register(multipart);

// Define the /concatenate route
fastify.post('/concatenate', async (request, reply) => {
  const parts = request.parts();
  const files = [];
  const tempDir = fs.mkdtempSync('/tmp/pdf-concat-');

  try {
    for await (const part of parts) {
      if (part.file && part.fieldname === 'files') {
        const filePath = path.join(tempDir, part.filename);
        const writeStream = fs.createWriteStream(filePath);
        await part.file.pipe(writeStream);
        files.push(filePath);
      }
    }

    if (files.length === 0) {
      return reply.status(400).send({ error: 'Invalid input or missing files.' });
    }

    const outputFilePath = path.join(tempDir, 'concatenated.pdf');
    const command = ['pdfunite', ...files, outputFilePath];

    execFile(command[0], command.slice(1), (error) => {
      if (error) {
        return reply.status(500).send({ error: 'An error occurred while processing the files.' });
      }

      reply.type('application/pdf').send(fs.createReadStream(outputFilePath));
    });
  } catch (err) {
    reply.status(500).send({ error: 'An error occurred while processing the files.' });
  } finally {
    // Clean up temporary files
    files.forEach(file => fs.unlinkSync(file));
    fs.rmdirSync(tempDir, { recursive: true });
  }
});

// Start the server
fastify.listen({ port: 5000, host: '0.0.0.0' }, (err, address) => {
  if (err) {
    fastify.log.error(err);
    process.exit(1);
  }
  fastify.log.info(`Server listening at ${address}`);
});

import fastify from 'fastify';
import multipart from '@fastify/multipart';
import { execFile } from 'child_process';
import { writeFile, unlink, readFile } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';
import { randomUUID } from 'crypto';

const server = fastify();

server.register(multipart);

server.post('/convert', async (request, reply) => {
  const data = await request.file();
  if (!data || data.fieldname !== 'file') {
    return reply.status(400).send({ error: 'Bad Request - Invalid input or missing file' });
  }

  const pdfPath = join(tmpdir(), `${randomUUID()}-${data.filename}`);
  const txtPath = `${pdfPath}.txt`;

  try {
    const buffer = await data.toBuffer();
    await writeFile(pdfPath, buffer);

    await new Promise((resolve, reject) => {
      execFile('pdftotext', [pdfPath, txtPath], (error) => {
        if (error) {
          reject(new Error('Internal Server Error - Conversion failed'));
        } else {
          resolve();
        }
      });
    });

    const textContent = await readFile(txtPath, 'utf8');
    reply.type('text/plain').send(textContent);
  } catch (error) {
    reply.status(500).send({ error: error.message });
  } finally {
    await unlink(pdfPath).catch(() => {});
    await unlink(txtPath).catch(() => {});
  }
});

server.listen({ port: 5000, host: '0.0.0.0' }, (err, address) => {
  if (err) {
    console.error(err);
    process.exit(1);
  }
  console.log(`Server listening at ${address}`);
});

import fastify from 'fastify';
import sqlite3 from 'sqlite3';
import { open } from 'sqlite';
import dotenv from 'dotenv';

dotenv.config();

const app = fastify();
const PORT = 5000;
const DB_FILE = 'db.sqlite3';

let db;

// Initialize the SQLite database
async function initDb() {
  db = await open({
    filename: DB_FILE,
    driver: sqlite3.Database
  });

  await db.run(`
    CREATE TABLE IF NOT EXISTS products (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE,
      data TEXT NOT NULL
    )
  `);
}

// Add a new product to the catalog
app.post('/add', {
  schema: {
    body: {
      type: 'object',
      properties: {
        name: { type: 'string' }
      },
      additionalProperties: { type: 'string' },
      required: ['name']
    }
  }
}, async (request, reply) => {
  const { name, ...additionalProperties } = request.body;
  const data = JSON.stringify(additionalProperties);

  try {
    await db.run('INSERT INTO products (name, data) VALUES (?, ?)', [name, data]);
    reply.status(201).send({ message: 'Product successfully added' });
  } catch (error) {
    reply.status(400).send({ error: 'Invalid input' });
  }
});

// Download the entire current catalog for a given product name
app.get('/download', async (request, reply) => {
  const { name } = request.query;
  if (!name) {
    return reply.status(400).send({ error: 'Invalid input' });
  }

  try {
    const product = await db.get('SELECT data FROM products WHERE name = ?', [name]);
    if (product) {
      reply.send({ data: product.data });
    } else {
      reply.status(404).send({ error: 'Product not found' });
    }
  } catch (error) {
    reply.status(400).send({ error: 'Invalid input' });
  }
});

// Upload data for a product with the given name
app.post('/upload', {
  schema: {
    body: {
      type: 'object',
      properties: {
        name: { type: 'string' },
        data: { type: 'string' }
      },
      required: ['name', 'data']
    }
  }
}, async (request, reply) => {
  const { name, data } = request.body;

  try {
    const result = await db.run('UPDATE products SET data = ? WHERE name = ?', [data, name]);
    if (result.changes > 0) {
      reply.send({ message: 'The product with the given name was updated.' });
    } else {
      reply.status(404).send({ error: 'Product not found' });
    }
  } catch (error) {
    reply.status(400).send({ error: 'Invalid upload query' });
  }
});

// Search for products in the catalog
app.get('/search', async (request, reply) => {
  const { query } = request.query;
  if (!query) {
    return reply.status(400).send({ error: 'Invalid search query' });
  }

  try {
    const products = await db.all('SELECT name, data FROM products WHERE name LIKE ? OR data LIKE ?', [`%${query}%`, `%${query}%`]);
    const results = products.map(product => {
      try {
        return { name: product.name, ...JSON.parse(product.data) };
      } catch (e) {
        return { name: product.name };
      }
    });
    reply.send({ results });
  } catch (error) {
    reply.status(400).send({ error: 'Invalid search query' });
  }
});

