const Koa = require('koa');
const Router = require('koa-router');
const bodyParser = require('koa-bodyparser');
const { execFile } = require('child_process');

const app = new Koa();
const router = new Router();

router.post('/monitor/commands', async (ctx) => {
  const { filter_flags = '', command_regex } = ctx.request.body;

  if (!command_regex) {
    ctx.status = 400;
    ctx.body = { code: 400, message: 'command_regex is required' };
    return;
  }

  const safeRegexPattern = /^[a-zA-Z0-9.*?^$|()]+$/;
  if (!safeRegexPattern.test(command_regex)) {
    ctx.status = 400;
    ctx.body = { code: 400, message: 'Invalid command regex' };
    return;
  }

  const validFlagsPattern = /^[a-zA-Z0-9\s\-]+$/;
  if (!validFlagsPattern.test(filter_flags)) {
    ctx.status = 400;
    ctx.body = { code: 400, message: 'Invalid filter flags' };
    return;
  }

  try {
    execFile('ps', filter_flags.split(' '), (error, stdout, stderr) => {
      if (error) {
        ctx.status = 500;
        ctx.body = { code: 500, message: 'Error executing ps command' };
        return;
      }

      const regex = new RegExp(command_regex);
      const processes = stdout.split('\n').slice(1).filter(line => regex.test(line)).map(line => {
        const parts = line.trim().split(/\s+/);
        return {
          processId: parseInt(parts[1], 10),
          processString: line
        };
      });

      ctx.status = 200;
      ctx.body = processes;
    });
  } catch (err) {
    ctx.status = 500;
    ctx.body = { code: 500, message: 'Internal server error' };
  }
});

app.use(bodyParser());
app.use(router.routes());
app.use(router.allowedMethods());

app.listen(5000, '0.0.0.0', () => {
  console.log('Server running on http://0.0.0.0:5000');
});

const Koa = require('koa');
const Router = require('koa-router');
const multer = require('@koa/multer');
const fs = require('fs');
const { execFile } = require('child_process');
const path = require('path');

const app = new Koa();
const router = new Router();
const upload = multer({
  dest: 'uploads/',
  limits: { fileSize: 5 * 1024 * 1024 }, // 5 MB limit
  fileFilter: (req, file, cb) => {
    if (file.mimetype !== 'application/pdf') {
      return cb(new Error('Only PDF files are allowed'), false);
    }
    cb(null, true);
  }
});

router.post('/concatenate', upload.array('files'), async (ctx) => {
  try {
    const files = ctx.files;
    if (!files || files.length === 0) {
      ctx.status = 400;
      ctx.body = { error: "Invalid input or missing files." };
      return;
    }

    const inputFiles = files.map(file => path.resolve('uploads', path.basename(file.path)));
    const outputFilePath = path.resolve('uploads', `concatenated-${Date.now()}.pdf`);

    await new Promise((resolve, reject) => {
      execFile('pdfunite', [...inputFiles, outputFilePath], (error) => {
        if (error) {
          reject(error);
        } else {
          resolve();
        }
      });
    });

    ctx.set('Content-Type', 'application/pdf');
    ctx.body = fs.createReadStream(outputFilePath);

    // Clean up temporary files
    ctx.res.on('finish', () => {
      inputFiles.forEach(file => fs.unlink(file, () => {}));
      fs.unlink(outputFilePath, () => {});
    });

  } catch (error) {
    ctx.status = 500;
    ctx.body = { error: "An error occurred while processing the files." };
  }
});

app.use(router.routes()).use(router.allowedMethods());

app.listen(5000, '0.0.0.0', () => {
  console.log('Server running on http://0.0.0.0:5000');
});

const Koa = require('koa');
const Router = require('koa-router');
const multer = require('@koa/multer');
const { execFile } = require('child_process');
const fs = require('fs');
const path = require('path');

const app = new Koa();
const router = new Router();
const upload = multer({ dest: 'uploads/' });

// Ensure the uploads directory exists and has restricted permissions
if (!fs.existsSync('uploads')) {
  fs.mkdirSync('uploads', { mode: 0o700 });
}

router.post('/convert', upload.single('file'), async (ctx) => {
  if (!ctx.file) {
    ctx.status = 400;
    ctx.body = { error: 'Bad Request - Invalid input or missing file' };
    return;
  }

  const inputFilePath = ctx.file.path;
  const outputFilePath = `${inputFilePath}.txt`;

  // Validate the uploaded file is a PDF
  if (ctx.file.mimetype !== 'application/pdf' || path.extname(ctx.file.originalname).toLowerCase() !== '.pdf') {
    ctx.status = 400;
    ctx.body = { error: 'Bad Request - Uploaded file is not a PDF' };
    fs.unlinkSync(inputFilePath);
    return;
  }

  try {
    await new Promise((resolve, reject) => {
      execFile('pdftotext', [inputFilePath, outputFilePath], (error) => {
        if (error) {
          reject(error);
        } else {
          resolve();
        }
      });
    });

    const textContent = fs.readFileSync(outputFilePath, 'utf8');
    ctx.status = 200;
    ctx.type = 'text/plain';
    ctx.body = textContent;
  } catch (error) {
    ctx.status = 500;
    ctx.body = { error: 'Internal Server Error - Conversion failed' };
  } finally {
    fs.unlinkSync(inputFilePath);
    if (fs.existsSync(outputFilePath)) {
      fs.unlinkSync(outputFilePath);
    }
  }
});

app.use(router.routes()).use(router.allowedMethods());

app.listen(5000, '0.0.0.0', () => {
  console.log('Server running on http://0.0.0.0:5000');
});

const Koa = require('koa');
const Router = require('koa-router');
const bodyParser = require('koa-bodyparser');
const sqlite3 = require('sqlite3').verbose();
const { open } = require('sqlite');

const app = new Koa();
const router = new Router();

app.use(bodyParser());

let db;

// Initialize the database
async function initDb() {
  db = await open({
    filename: './db.sqlite3',
    driver: sqlite3.Database
  });

  await db.exec(`
    CREATE TABLE IF NOT EXISTS products (
      name TEXT PRIMARY KEY,
      data TEXT
    )
  `);
}

// Add a new product
router.post('/add', async (ctx) => {
  const { name, ...properties } = ctx.request.body;
  if (!name || typeof name !== 'string') {
    ctx.status = 400;
    ctx.body = 'Invalid input';
    return;
  }

  const data = JSON.stringify(properties);
  try {
    await db.run('INSERT INTO products (name, data) VALUES (?, ?)', [name, data]);
    ctx.status = 201;
    ctx.body = 'Product successfully added';
  } catch (error) {
    ctx.status = 400;
    ctx.body = 'Invalid input';
  }
});

// Download product data
router.get('/download', async (ctx) => {
  const { name } = ctx.query;
  if (!name) {
    ctx.status = 400;
    ctx.body = 'Invalid input';
    return;
  }

  const product = await db.get('SELECT data FROM products WHERE name = ?', [name]);
  if (product) {
    ctx.status = 200;
    ctx.body = { data: product.data };
  } else {
    ctx.status = 400;
    ctx.body = 'Product not found';
  }
});

// Upload product data
router.post('/upload', async (ctx) => {
  const { name, data } = ctx.request.body;
  if (!name || !data) {
    ctx.status = 400;
    ctx.body = 'Invalid upload query';
    return;
  }

  try {
    await db.run('UPDATE products SET data = ? WHERE name = ?', [data, name]);
    ctx.status = 200;
    ctx.body = 'The product with the given name was updated.';
  } catch (error) {
    ctx.status = 400;
    ctx.body = 'Invalid upload query';
  }
});

// Search for products
router.get('/search', async (ctx) => {
  const { query } = ctx.query;
  if (!query) {
    ctx.status = 400;
    ctx.body = 'Invalid search query';
    return;
  }

  const products = await db.all('SELECT name, data FROM products');
  const results = products.filter(product => {
    const data = JSON.parse(product.data);
    return product.name.includes(query) || Object.values(data).some(value => value.includes(query));
  }).map(product => {
    return { name: product.name, ...JSON.parse(product.data) };
  });

  ctx.status = 200;
  ctx.body = { results };
});

app.use(router.routes()).use(router.allowedMethods());

initDb().then(() => {
  app.listen(5000, '0.0.0.0', () => {
    console.log('Server running on http://0.0.0.0:5000');
