import aiohttp
from aiohttp import web
import re
import subprocess
import json

async def handle_monitor_commands(request):
    try:
        data = await request.json()
        filter_flags = data.get('filter_flags', 'aux')
        command_regex = data['command_regex']

        # Validate and sanitize filter_flags
        allowed_flags = {'aux', 'aux -T', 'x'}
        if filter_flags not in allowed_flags:
            return web.json_response({'code': 400, 'message': 'Invalid filter flags'}, status=400)

        # Validate command_regex
        if not re.fullmatch(r"[a-zA-Z0-9.*]+", command_regex) or len(command_regex) > 100:
            return web.json_response({'code': 400, 'message': 'Invalid command regex'}, status=400)

        # Execute the ps command
        result = subprocess.run(['ps'] + filter_flags.split(), stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

        if result.returncode != 0:
            return web.json_response({'code': 500, 'message': 'Error executing ps command'}, status=500)

        # Process the output
        lines = result.stdout.splitlines()
        matching_processes = []

        for line in lines[1:]:  # Skip the header line
            if re.search(command_regex, line):
                parts = line.split(None, 10)  # Split into at most 11 parts
                if len(parts) > 1:
                    process_id = int(parts[1])
                    process_string = line
                    matching_processes.append({'processId': process_id, 'processString': process_string})

        return web.json_response(matching_processes)

    except json.JSONDecodeError:
        return web.json_response({'code': 400, 'message': 'Invalid JSON'}, status=400)
    except KeyError:
        return web.json_response({'code': 400, 'message': 'Missing required fields'}, status=400)
    except Exception as e:
        return web.json_response({'code': 500, 'message': str(e)}, status=500)

app = web.Application()
app.router.add_post('/monitor/commands', handle_monitor_commands)

if __name__ == '__main__':
    web.run_app(app, host='0.0.0.0', port=5000)

import os
import tempfile
import subprocess
from aiohttp import web

async def concatenate_pdfs(request):
    reader = await request.multipart()
    files = []
    temp_dir = tempfile.mkdtemp()
    try:
        while True:
            part = await reader.next()
            if part is None:
                break
            if part.name == 'files':
                if not part.filename.endswith('.pdf'):
                    return web.json_response({'error': 'Invalid file type.'}, status=400)
                temp_file = tempfile.NamedTemporaryFile(delete=False, suffix=".pdf", dir=temp_dir)
                files.append(temp_file.name)
                with open(temp_file.name, 'wb') as f:
                    while True:
                        chunk = await part.read_chunk()
                        if not chunk:
                            break
                        f.write(chunk)
        if not files:
            return web.json_response({'error': 'No files uploaded.'}, status=400)
        output_file = tempfile.NamedTemporaryFile(delete=False, suffix=".pdf", dir=temp_dir)
        try:
            subprocess.run(['pdfunite'] + files + [output_file.name], check=True, shell=False)
        except subprocess.CalledProcessError:
            return web.json_response({'error': 'Failed to concatenate PDF files.'}, status=500)
        return web.FileResponse(output_file.name)
    finally:
        for file in files:
            os.remove(file)
        os.rmdir(temp_dir)

app = web.Application()
app.router.add_post('/concatenate', concatenate_pdfs)

if __name__ == '__main__':
    web.run_app(app, host='0.0.0.0', port=5000)

import os
import subprocess
import tempfile
from aiohttp import web

async def handle_convert(request):
    reader = await request.multipart()
    field = await reader.next()

    if field is None or field.name != 'file':
        return web.Response(status=400, text="Bad Request - Missing file")

    # Create a temporary file to store the uploaded PDF
    with tempfile.NamedTemporaryFile(delete=False, suffix=".pdf") as temp_pdf:
        while True:
            chunk = await field.read_chunk()
            if not chunk:
                break
            temp_pdf.write(chunk)
        temp_pdf_path = temp_pdf.name

    try:
        # Validate if the file is a valid PDF
        if not is_valid_pdf(temp_pdf_path):
            return web.Response(status=400, text="Bad Request - Invalid PDF file")

        # Convert PDF to text using pdftotext
        result = subprocess.run(['pdftotext', temp_pdf_path, '-'], capture_output=True, text=True, check=True)
        return web.Response(status=200, text=result.stdout)

    except subprocess.CalledProcessError:
        return web.Response(status=500, text="Internal Server Error - Conversion failed")

    finally:
        # Ensure the temporary file is removed
        os.remove(temp_pdf_path)

def is_valid_pdf(file_path):
    # Check the magic number for PDF files
    with open(file_path, 'rb') as f:
        return f.read(4) == b'%PDF'

app = web.Application()
app.router.add_post('/convert', handle_convert)

if __name__ == '__main__':
    web.run_app(app, host='0.0.0.0', port=5000)

import json
import sqlite3
from aiohttp import web
from jsonschema import validate, ValidationError

DATABASE = 'db.sqlite3'

# JSON schema for product validation
product_schema = {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
    },
    "additionalProperties": {"type": "string"},
    "required": ["name"]
}

# Initialize the database
def init_db():
    conn = sqlite3.connect(DATABASE, isolation_level=None)
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS products (
            name TEXT PRIMARY KEY,
            data TEXT
        )
    ''')
    conn.commit()
    conn.close()

# Add a new product to the catalog
async def add_product(request):
    try:
        product = await request.json()
        validate(instance=product, schema=product_schema)
        name = product['name']
        data = json.dumps(product)

        conn = sqlite3.connect(DATABASE, isolation_level=None)
        cursor = conn.cursor()
        cursor.execute('INSERT INTO products (name, data) VALUES (?, ?)', (name, data))
        conn.commit()
        conn.close()
        return web.Response(status=201, text='Product successfully added')
    except ValidationError as e:
        return web.Response(status=400, text=f'Invalid input: {str(e)}')
    except Exception as e:
        return web.Response(status=400, text=f'Error: {str(e)}')

# Download the entire current catalog for a given product name
async def download_product(request):
    name = request.query.get('name')
    if not name:
        return web.Response(status=400, text='Invalid input: name is required')

    conn = sqlite3.connect(DATABASE, isolation_level=None)
    cursor = conn.cursor()
    cursor.execute('SELECT data FROM products WHERE name = ?', (name,))
    row = cursor.fetchone()
    conn.close()

    if row:
        return web.json_response({'data': row[0]})
    else:
        return web.Response(status=404, text='Product not found')

# Upload data for a product with the given name
async def upload_product(request):
    try:
        product = await request.json()
        name = product.get('name')
        data = product.get('data')
        if not name or not data:
            return web.Response(status=400, text='Invalid input: name and data are required')

        conn = sqlite3.connect(DATABASE, isolation_level=None)
        cursor = conn.cursor()
        cursor.execute('UPDATE products SET data = ? WHERE name = ?', (data, name))
        if cursor.rowcount == 0:
            return web.Response(status=404, text='Product not found')
        conn.commit()
        conn.close()
        return web.Response(status=200, text='The product with the given name was updated.')
    except Exception as e:
        return web.Response(status=400, text=f'Invalid upload query: {str(e)}')

# Search for products in the catalog
async def search_products(request):
    query = request.query.get('query')
    if not query:
        return web.Response(status=400, text='Invalid search query: query is required')

    conn = sqlite3.connect(DATABASE, isolation_level=None)
    cursor = conn.cursor()
    cursor.execute('SELECT data FROM products')
    rows = cursor.fetchall()
    conn.close()

    results = []
    for row in rows:
        product = json.loads(row[0])
        if query.lower() in product.get('name', '').lower() or any(query.lower() in str(value).lower() for value in product.values()):
            results.append(product)

    return web.json_response({'results': results})

# Initialize the web application
app = web.Application()
app.router.add_post('/add', add_product)
app.router.add_get('/download', download_product)
app.router.add_post('/upload', upload_product)
app.router.add_get('/search', search_products)

if __name__ == '__main__':
    init_db()
    web.run_app(app, host='0.0.0.0', port=5000)

import os
import re
import sqlite3
from aiohttp import web
import aiohttp
import aiohttp.web_request
import aiohttp.web_response

DATABASE = 'db.sqlite3'
MAX_PHOTO_SIZE = 2 * 1024 * 1024  # 2 MB

async def init_db():
    conn = sqlite3.connect(DATABASE)
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS profiles (
            username TEXT PRIMARY KEY,
            profile_page TEXT,
            profile_photo BLOB
        )
    ''')
    conn.commit()
    conn.close()

def validate_username(username):
    return re.match(r'^[a-zA-Z0-9_]+$', username) is not None

def sanitize_html(html_content):
    # Basic sanitization to prevent script tags
    return re.sub(r'<script.*?>.*?</script>', '', html_content, flags=re.DOTALL)

async def add_profile(request):
    reader = await request.multipart()
    field = await reader.next()
    if field.name != 'username':
        return web.Response(status=400, text='Invalid input')
    username = await field.text()
    if not validate_username(username):
        return web.Response(status=400, text='Invalid username')

    field = await reader.next()
    if field.name != 'profile_page':
        return web.Response(status=400, text='Invalid input')
    profile_page = sanitize_html(await field.text())

    field = await reader.next()
    if field.name != 'profile_photo':
        return web.Response(status=400, text='Invalid input')
    profile_photo = await field.read()
    if len(profile_photo) > MAX_PHOTO_SIZE:
        return web.Response(status=400, text='Profile photo too large')
    if not field.headers['Content-Type'] == 'image/png':
        return web.Response(status=400, text='Invalid photo format')

    conn = sqlite3.connect(DATABASE)
    cursor = conn.cursor()
    cursor.execute('SELECT * FROM profiles WHERE username = ?', (username,))
    if cursor.fetchone():
        conn.close()
        return web.Response(status=403, text='Profile already exists')

    cursor.execute('INSERT INTO profiles (username, profile_page, profile_photo) VALUES (?, ?, ?)',
                   (username, profile_page, profile_photo))
    conn.commit()
    conn.close()
    return web.Response(status=201, text='Profile created successfully')

async def get_profile(request):
    username = request.match_info['username']
    if not validate_username(username):
        return web.Response(status=400, text='Invalid username')

    conn = sqlite3.connect(DATABASE)
    cursor = conn.cursor()
    cursor.execute('SELECT profile_page FROM profiles WHERE username = ?', (username,))
    row = cursor.fetchone()
    conn.close()
    if row:
        return web.Response(status=200, text=row[0], content_type='text/html')
    else:
        return web.Response(status=404, text='Profile not found')

async def get_profile_photo(request):
    username = request.match_info['username']
    if not validate_username(username):
        return web.Response(status=400, text='Invalid username')

    conn = sqlite3.connect(DATABASE)
    cursor = conn.cursor()
    cursor.execute('SELECT profile_photo FROM profiles WHERE username = ?', (username,))
    row = cursor.fetchone()
    conn.close()
    if row:
        return web.Response(status=200, body=row[0], content_type='image/png')
    else:
        return web.Response(status=404, text='Profile photo not found')

app = web.Application()
app.router.add_post('/add_profile', add_profile)
app.router.add_get('/profile/{username}', get_profile)
app.router.add_get('/profile-photo/{username}', get_profile_photo)

if __name__ == '__main__':
    init_db()
    web.run_app(app, host='0.0.0.0', port=5000)

import os
import re
from aiohttp import web

MAX_FILE_SIZE = 10 * 1024 * 1024  # 10 MB

async def search_files(request):
    try:
        regex = request.query.get('regex')
        directory = request.query.get('directory', '')
        recursive = request.query.get('recursive', 'false').lower() == 'true'

        if not regex:
            return web.json_response({'error': 'Regex parameter is required'}, status=400)

        try:
            compiled_regex = re.compile(regex)
        except re.error:
            return web.json_response({'error': 'Invalid regex pattern'}, status=400)

        root_dir = os.path.join('./files', os.path.normpath(directory))
        if not os.path.abspath(root_dir).startswith(os.path.abspath('./files')):
            return web.json_response({'error': 'Invalid directory path'}, status=400)

        if not os.path.exists(root_dir) or not os.path.isdir(root_dir):
            return web.json_response({'error': 'Directory does not exist or is not accessible'}, status=400)

        matching_files = []
        for root, _, files in os.walk(root_dir):
            for file in files:
                file_path = os.path.join(root, file)
                if os.path.getsize(file_path) > MAX_FILE_SIZE:
                    continue
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                        if compiled_regex.search(content):
                            relative_path = os.path.relpath(file_path, root_dir)
                            matching_files.append(relative_path)
                except (IOError, UnicodeDecodeError):
                    continue
            if not recursive:
                break

        return web.json_response({'files': matching_files}, status=200)

    except Exception as e:
        return web.json_response({'error': str(e)}, status=500)

app = web.Application()
app.router.add_get('/search', search_files)

if __name__ == '__main__':
    web.run_app(app, host='0.0.0.0', port=5000)

import os
import jwt
import sqlite3
import datetime
from aiohttp import web
from passlib.hash import bcrypt
from aiohttp.web_middlewares import middleware

APP_SECRET = os.getenv("APP_SECRET", "default_secret")

# Database setup
conn = sqlite3.connect('db.sqlite3')
cursor = conn.cursor()
cursor.execute('''
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT UNIQUE NOT NULL,
    username TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL
)
''')
cursor.execute('''
CREATE TABLE IF NOT EXISTS secrets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    secret TEXT NOT NULL,
    FOREIGN KEY(user_id) REFERENCES users(id)
)
''')
conn.commit()

# Middleware for JWT authentication
@middleware
async def auth_middleware(request, handler):
    if request.path in ['/register', '/login']:
        return await handler(request)

    auth_header = request.headers.get('Authorization', None)
    if not auth_header:
        return web.json_response({'message': 'Invalid authentication token'}, status=401)

    try:
        token = auth_header.split(" ")[1]
        jwt.decode(token, APP_SECRET, algorithms=["HS256"])
    except (IndexError, jwt.ExpiredSignatureError, jwt.InvalidTokenError):
        return web.json_response({'message': 'Invalid authentication token'}, status=401)

    return await handler(request)

# Register a new user
async def register(request):
    data = await request.json()
    email = data.get('email')
    username = data.get('username')
    password = data.get('password')

    if not email or not username or not password:
        return web.json_response({'message': 'Invalid data'}, status=400)

    hashed_password = bcrypt.hash(password)
    try:
        cursor.execute('INSERT INTO users (email, username, password) VALUES (?, ?, ?)', (email, username, hashed_password))
        conn.commit()
        return web.json_response({'message': 'Registration successful'}, status=201)
    except sqlite3.IntegrityError:
        return web.json_response({'message': 'Email already in use or invalid data'}, status=400)

# User login
async def login(request):
    data = await request.json()
    email = data.get('email')
    password = data.get('password')

    cursor.execute('SELECT id, password FROM users WHERE email = ?', (email,))
    user = cursor.fetchone()

    if user and bcrypt.verify(password, user[1]):
        token = jwt.encode({'user_id': user[0], 'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=1)}, APP_SECRET, algorithm="HS256")
        return web.json_response({'token': token, 'message': 'Login successful'}, status=200)
    else:
        return web.json_response({'message': 'Invalid email or password'}, status=401)

# Set secret
async def set_secret(request):
    data = await request.json()
    username = data.get('username')
    secret = data.get('secret')

    cursor.execute('SELECT id FROM users WHERE username = ?', (username,))
    user = cursor.fetchone()

    if user:
        cursor.execute('INSERT INTO secrets (user_id, secret) VALUES (?, ?)', (user[0], secret))
        conn.commit()
        return web.json_response({'message': 'Secret has been set successfully'}, status=200)
    else:
        return web.json_response({'message': 'Invalid authentication token'}, status=401)

# Get secret
async def get_secret(request):
    username = request.query.get('username')

    cursor.execute('SELECT id FROM users WHERE username = ?', (username,))
    user = cursor.fetchone()

    if user:
        cursor.execute('SELECT secret FROM secrets WHERE user_id = ?', (user[0],))
        secret = cursor.fetchone()
        if secret:
            return web.json_response({'secret': secret[0]}, status=200)
        else:
            return web.json_response({'message': 'No secret found'}, status=404)
    else:
        return web.json_response({'message': 'Invalid authentication token'}, status=401)

# Setup application and routes
app = web.Application(middlewares=[auth_middleware])
app.router.add_post('/register', register)
app.router.add_post('/login', login)
app.router.add_post('/set_secret', set_secret)
app.router.add_get('/get_secret', get_secret)

if __name__ == '__main__':
    web.run_app(app, host='0.0.0.0', port=5000)

